// The published works (generated by scripts/import-works.ts into src/site/works.gen.ts, where Home can read them too) and
// the wall this page shows.
import { SLATE } from '../../i18n/works.ts';
import { rankedWorks, wallEntries } from '../../lib/works.ts';
import { WORKS } from '../../site/works.gen.ts';

export { WORKS };

/** Real works first; "rendering" placeholders of the slate while fewer than six are published. */
export const WALL = wallEntries(WORKS, SLATE);

/** The work the hero plays: the best-ranked landscape work, else the best-ranked one. */
export const HERO_WORK = rankedWorks(WORKS).find((work) => work.orientation === 'landscape') ?? rankedWorks(WORKS)[0];
